def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    x = rng.uniform(lb, ub, (1, dim))
    best_x = x.copy()
    best_f = func(x)
    threshold_improvement = 0.01

    for _ in range(budget):
        s = 10 * (ub - lb) / (budget + 1)
        new_x = clip(x + rng.uniform(-s, s, (1, dim)))
        f_new = func(new_x)

        if f_new < best_f:
            x = new_x
            best_x = x.copy()
            best_f = f_new

    return best_x[0]
